/* Find a shortest distinguishing word for 2 given binary DFAs (maximum 12 states each). */
#include <stdio.h>
int main(void){int n,m,fa[12],fb[12],a[12][2],b[12][2],p[144],ch[144],q[144],seen[144]={0},head=0,tail=0;int s,t;if(scanf("%d %d",&n,&m)!=2||n<1||m<1||n>12||m>12)return 1;for(int i=0;i<n;i++)if(scanf("%d",&fa[i])!=1||fa[i]<0||fa[i]>1)return 1;for(int i=0;i<m;i++)if(scanf("%d",&fb[i])!=1||fb[i]<0||fb[i]>1)return 1;for(int i=0;i<n;i++)for(int c=0;c<2;c++)if(scanf("%d",&a[i][c])!=1||a[i][c]<0||a[i][c]>=n)return 1;for(int i=0;i<m;i++)for(int c=0;c<2;c++)if(scanf("%d",&b[i][c])!=1||b[i][c]<0||b[i][c]>=m)return 1;if(scanf("%d %d",&s,&t)!=2||s<0||s>=n||t<0||t>=m)return 1;int root=s*m+t;q[tail++]=root;seen[root]=1;p[root]=-1;while(head<tail){int x=q[head++],u=x/m,v=x%m;if(fa[u]!=fb[v]){char word[145];int len=0;while(p[x]!=-1){word[len++]=(char)('0'+ch[x]);x=p[x];}printf("DISTINGUISHING:");if(!len)printf(" epsilon");while(len)putchar(word[--len]);putchar('\n');return 0;}for(int c=0;c<2;c++){int y=a[u][c]*m+b[v][c];if(!seen[y]){seen[y]=1;p[y]=x;ch[y]=c;q[tail++]=y;}}}puts("EQUIVALENT");return 0;}